{-# LANGUAGE QuasiQuotes #-}

-- | The C runtime linked in to every compiled program: allocation, closure reference counting, the IO inbuilts, and
-- the program entry point. It is written next to the generated IR at compile time.
module Codegen.Runtime
  ( runtimeSource
  ) where

import           Text.RawString.QQ


runtimeSource :: String
runtimeSource = [r|
#include <inttypes.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Generated by the compiler. */
void praxis_init(void);
void praxis_main(void);

void praxis_abort(const char* msg) {
  fflush(stdout);
  fprintf(stderr, "error: %s\n", msg);
  exit(1);
}

void* praxis_alloc(int64_t size) {
  void* p = malloc(size > 0 ? (size_t)size : 1);
  if (p == NULL) praxis_abort("out of memory");
  return p;
}

void praxis_free(void* p) {
  free(p);
}

/* Closures: { int64 count, void* code, void (*drop_env)(void*), captures.. }. A count of zero marks an immortal
 * (static) closure. */
struct closure {
  int64_t count;
  void* code;
  void (*drop_env)(void*);
};

void praxis_retain(void* c) {
  struct closure* closure = c;
  if (closure->count != 0) closure->count++;
}

void praxis_release(void* c) {
  struct closure* closure = c;
  if (closure->count != 0 && --closure->count == 0) {
    if (closure->drop_env != NULL) closure->drop_env(c);
    free(c);
  }
}

/* Strings: { int64 length, bytes.. } */
struct string {
  int64_t length;
  char bytes[];
};

void* praxis_string_copy(void* s) {
  struct string* src = s;
  struct string* dst = praxis_alloc(sizeof(struct string) + src->length);
  dst->length = src->length;
  memcpy(dst->bytes, src->bytes, src->length);
  return dst;
}

/* Reads a line holding an integer (like the interpreter's readLn). */
int64_t praxis_get_int(void) {
  long long n;
  if (scanf("%lld", &n) != 1) praxis_abort("failed to read an integer");
  int c;
  while ((c = getchar()) != EOF && c != '\n') {}
  return n;
}

void praxis_put_int(int64_t n) {
  printf("%" PRId64 "\n", n);
}

void praxis_put_uint(uint64_t n) {
  printf("%" PRIu64 "\n", n);
}

void* praxis_get_str(void) {
  size_t capacity = 1024, length = 0;
  char* buffer = praxis_alloc(capacity);
  size_t n;
  while ((n = fread(buffer + length, 1, capacity - length, stdin)) > 0) {
    length += n;
    if (length == capacity) {
      capacity *= 2;
      buffer = realloc(buffer, capacity);
      if (buffer == NULL) praxis_abort("out of memory");
    }
  }
  struct string* s = praxis_alloc(sizeof(struct string) + length);
  s->length = length;
  memcpy(s->bytes, buffer, length);
  free(buffer);
  return s;
}

void praxis_put_str(void* p) {
  struct string* s = p;
  fwrite(s->bytes, 1, s->length, stdout);
}

void praxis_put_str_ln(void* p) {
  praxis_put_str(p);
  putchar('\n');
}

/* Show, in the format of the interpreter. */

void praxis_show_lit(const char* s) {
  fputs(s, stdout);
}

void praxis_show_int(int64_t n) {
  printf("%" PRId64, n);
}

void praxis_show_uint(uint64_t n) {
  printf("%" PRIu64, n);
}

void praxis_show_bool(bool b) {
  fputs(b ? "True" : "False", stdout);
}

static void show_char_escaped(uint32_t c, char quote) {
  if (c == (uint32_t)quote) printf("\\%c", quote);
  else if (c == '\\') fputs("\\\\", stdout);
  else if (c == '\n') fputs("\\n", stdout);
  else if (c == '\t') fputs("\\t", stdout);
  else if (c == '\r') fputs("\\r", stdout);
  else if (c < 0x20 || c >= 0x7f) printf("\\%" PRIu32, c);
  else putchar((int)c);
}

void praxis_show_char(int32_t c) {
  putchar('\'');
  show_char_escaped((uint32_t)c, '\'');
  putchar('\'');
}

/* Decode one UTF-8 code point, advancing the index. */
static uint32_t decode_utf8(const unsigned char* bytes, int64_t length, int64_t* i) {
  unsigned char b = bytes[*i];
  int extra = b >= 0xF0 ? 3 : b >= 0xE0 ? 2 : b >= 0xC0 ? 1 : 0;
  uint32_t c = extra == 3 ? (b & 0x07) : extra == 2 ? (b & 0x0F) : extra == 1 ? (b & 0x1F) : b;
  (*i)++;
  for (int k = 0; k < extra && *i < length; k++, (*i)++) c = (c << 6) | (bytes[*i] & 0x3F);
  return c;
}

void praxis_show_str(void* p) {
  struct string* s = p;
  putchar('"');
  int64_t i = 0;
  while (i < s->length) {
    uint32_t c = decode_utf8((const unsigned char*)s->bytes, s->length, &i);
    show_char_escaped(c, '"');
  }
  putchar('"');
}

int main(void) {
  praxis_init();
  praxis_main();
  fflush(stdout);
  return 0;
}
|]
